import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header for empty list', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header with correct columns', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv ends with newline', () => {
  const result = exportCsv([]);
  assert.equal(result[result.length - 1], '\n');
});

test('exportCsv exports single issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[1].includes('2026-10-01'));
  assert.ok(lines[1].includes('issued'));
});

test('exportCsv exports draft invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const result = exportCsv([inv]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('draft'));
});

test('exportCsv includes customer name', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.includes('Acme'));
});

test('exportCsv formats amounts as euros with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const result = exportCsv([issued]);

  const expectedTotal = (totals.total / 100).toFixed(2);
  assert.ok(result.includes(expectedTotal));
});

test('exportCsv no currency symbol in amounts', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(!result.includes('€'));
});

test('exportCsv escapes field with comma', () => {
  const inv = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.includes('"'));
});

test('exportCsv escapes field with double quote', () => {
  const inv = createInvoice({
    customerId: 'C-005',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.includes('""'));
});

test('exportCsv multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[2].includes('INV-2026-0002'));
});

test('exportCsv includes dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.includes('2026-10-31'));
});

test('exportCsv draft invoice has no number', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const result = exportCsv([inv]);
  const lines = result.split('\n');

  const fields = lines[1].split(',');
  assert.equal(fields[0], '');
});

test('exportCsv includes subtotal', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const result = exportCsv([issued]);

  const expectedSubtotal = (totals.subtotal / 100).toFixed(2);
  assert.ok(result.includes(expectedSubtotal));
});

test('exportCsv includes discount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const result = exportCsv([issued]);

  const expectedDiscount = (totals.discount / 100).toFixed(2);
  assert.ok(result.includes(expectedDiscount));
});

test('exportCsv includes VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const result = exportCsv([issued]);

  const expectedVat = (totals.vat / 100).toFixed(2);
  assert.ok(result.includes(expectedVat));
});

test('exportCsv calculates due for unpaid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const result = exportCsv([issued]);

  const expectedDue = (totals.total / 100).toFixed(2);
  assert.ok(result.includes(expectedDue));
});

test('exportCsv calculates due for paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-05' }).value;

  const result = exportCsv([paid]);

  assert.ok(result.includes(',0.00\n'));
});

test('exportCsv calculates due for partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: 5000, date: '2026-10-05' }).value;

  const result = exportCsv([paid]);
  const expectedDue = ((totals.total - 5000) / 100).toFixed(2);

  assert.ok(result.includes(expectedDue));
});

test('exportCsv with various statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(issued2);
  const paid2 = recordPayment(issued2, { amount: totals2.total, date: '2026-10-05' }).value;

  const result = exportCsv([inv1, issued1, paid2]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('draft'));
  assert.ok(lines[2].includes('issued'));
  assert.ok(lines[3].includes('paid'));
});

test('exportCsv properly formats decimal amounts', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.includes('0.50') || result.includes('0.61'));
});

test('exportCsv preserves invoice order', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const result = exportCsv([issued1, issued2, issued3]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[2].includes('INV-2026-0002'));
  assert.ok(lines[3].includes('INV-2026-0003'));
});

test('exportCsv handles unknown customer gracefully', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  inv.customerId = 'C-999';

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.length > 0);
});

test('exportCsv escapes double quote by doubling', () => {
  const inv = createInvoice({
    customerId: 'C-005',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = exportCsv([issued]);

  assert.ok(result.includes('""'));
  assert.ok(!result.includes('\\"'));
});

test('exportCsv lines separated by newline', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert.equal(lines[3], '');
});

